import React, { useState, useEffect } from 'react';
import { TrendingUp, Clock, Tag, AlertTriangle, CheckCircle, Eye, BarChart3 } from 'lucide-react';

const Analytics = () => {
  const [stats, setStats] = useState(null);
  const [trending, setTrending] = useState([]);
  const [quality, setQuality] = useState(null);
  const [diversity, setDiversity] = useState(null);
  const [trends, setTrends] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');

  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        setLoading(true);

        // 并行获取统计数据
        const [statsRes, trendingRes, qualityRes, diversityRes, trendsRes] = await Promise.all([
          fetch('/api/analytics/stats'),
          fetch('/api/analytics/trending?limit=10'),
          fetch('/api/analytics/quality'),
          fetch('/api/analytics/diversity'),
          fetch('/api/analytics/trends')
        ]);

        const [statsData, trendingData, qualityData, diversityData, trendsData] = await Promise.all([
          statsRes.json(),
          trendingRes.json(),
          qualityRes.json(),
          diversityRes.json(),
          trendsRes.json()
        ]);

        if (statsData.success) setStats(statsData.data);
        if (trendingData.success) setTrending(trendingData.data);
        if (qualityData.success) setQuality(qualityData.data);
        if (diversityData.success) setDiversity(diversityData.data);
        if (trendsData.success) setTrends(trendsData.data);
      } catch (error) {
        console.error('获取分析数据失败:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchAnalytics();
  }, []);

  const getRiskColor = (level) => {
    const colors = {
      'low': 'text-green-600 bg-green-100',
      'medium': 'text-yellow-600 bg-yellow-100',
      'high': 'text-red-600 bg-red-100'
    };
    return colors[level] || 'text-gray-600 bg-gray-100';
  };

  const getRiskIcon = (level) => {
    if (level === 'low') return <CheckCircle className="w-5 h-5" />;
    if (level === 'high') return <AlertTriangle className="w-5 h-5" />;
    return <Eye className="w-5 h-5" />;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
        <span className="ml-2 text-gray-600">加载数据分析中...</span>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {/* 页面标题 */}
      <div>
        <h1 className="text-3xl font-bold text-gray-900">数据分析</h1>
        <p className="text-gray-600 mt-2">AI资讯平台运营数据分析与内容多样性检测</p>
      </div>

      {/* 标签页导航 */}
      <div className="border-b border-gray-200">
        <nav className="flex space-x-8">
          {[
            { id: 'overview', label: '概览', icon: BarChart3 },
            { id: 'diversity', label: '信息茧房检测', icon: Eye },
            { id: 'trends', label: 'AI趋势分析', icon: TrendingUp }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-2 py-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                activeTab === tab.id
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              <tab.icon className="w-4 h-4" />
              <span>{tab.label}</span>
            </button>
          ))}
        </nav>
      </div>

      {/* 概览标签页 */}
      {activeTab === 'overview' && (
        <div className="space-y-8">
          {/* 统计卡片 */}
          {stats && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-blue-100 rounded-lg">
                    <TrendingUp className="w-6 h-6 text-blue-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">总资讯数</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.total}</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-green-100 rounded-lg">
                    <Clock className="w-6 h-6 text-green-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">今日新增</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.today}</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                <div className="flex items-center">
                  <div className="p-2 bg-purple-100 rounded-lg">
                    <Tag className="w-6 h-6 text-purple-600" />
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">资讯分类</p>
                    <p className="text-2xl font-bold text-gray-900">{Object.keys(stats.categories || {}).length}</p>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                <div className="flex items-center">
                  <div className={`p-2 rounded-lg ${diversity ? getRiskColor(diversity.riskLevel) : 'bg-gray-100'}`}>
                    {diversity ? getRiskIcon(diversity.riskLevel) : <Eye className="w-6 h-6 text-gray-600" />}
                  </div>
                  <div className="ml-4">
                    <p className="text-sm font-medium text-gray-500">多样性评分</p>
                    <p className="text-2xl font-bold text-gray-900">{diversity?.diversityScore || 0}%</p>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* 分类统计 */}
          {stats?.categories && (
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4">分类统计</h2>
              <div className="space-y-4">
                {Object.entries(stats.categories).map(([category, count]) => (
                  <div key={category} className="flex items-center justify-between">
                    <span className="text-gray-700">{category}</span>
                    <div className="flex items-center">
                      <div className="w-32 bg-gray-200 rounded-full h-2 mr-4">
                        <div 
                          className="bg-blue-600 h-2 rounded-full" 
                          style={{ 
                            width: `${Math.max((count / stats.total) * 100, 5)}%` 
                          }}
                        ></div>
                      </div>
                      <span className="text-sm font-medium text-gray-900">{count}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* 热门话题 */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <h2 className="text-xl font-semibold text-gray-900 mb-4">热门话题</h2>
            {trending.length > 0 ? (
              <div className="flex flex-wrap gap-2">
                {trending.map((topic, index) => (
                  <span
                    key={topic.keyword}
                    className="inline-flex items-center px-3 py-2 bg-gray-100 text-gray-800 rounded-lg text-sm"
                  >
                    <span className="w-6 h-6 bg-blue-600 text-white rounded-full flex items-center justify-center text-xs mr-2">
                      {index + 1}
                    </span>
                    {topic.keyword}
                    <span className="ml-2 text-gray-500">({topic.count})</span>
                  </span>
                ))}
              </div>
            ) : (
              <p className="text-gray-500">暂无热门话题数据</p>
            )}
          </div>

          {/* 内容质量分析 */}
          {quality && (
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4">内容质量分析</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="text-center p-4 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-gray-900">{quality.totalArticles}</p>
                  <p className="text-sm text-gray-500">总文章数</p>
                </div>
                <div className="text-center p-4 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-green-600">{quality.withImages}</p>
                  <p className="text-sm text-gray-500">含图片文章</p>
                </div>
                <div className="text-center p-4 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-blue-600">{quality.withDescriptions}</p>
                  <p className="text-sm text-gray-500">含详细描述</p>
                </div>
                <div className="text-center p-4 bg-gray-50 rounded-lg">
                  <p className="text-2xl font-bold text-purple-600">{quality.avgDescriptionLength}</p>
                  <p className="text-sm text-gray-500">平均描述长度</p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* 信息茧房检测标签页 */}
      {activeTab === 'diversity' && diversity && (
        <div className="space-y-6">
          {/* 多样性评分卡片 */}
          <div className={`rounded-lg p-6 ${
            diversity.riskLevel === 'low' ? 'bg-green-50 border border-green-200' :
            diversity.riskLevel === 'high' ? 'bg-red-50 border border-red-200' :
            'bg-yellow-50 border border-yellow-200'
          }`}>
            <div className="flex items-start justify-between">
              <div>
                <h2 className="text-xl font-semibold text-gray-900 flex items-center">
                  {getRiskIcon(diversity.riskLevel)}
                  <span className="ml-2">内容多样性评分</span>
                </h2>
                <p className="text-gray-600 mt-1">{diversity.riskMessage}</p>
              </div>
              <div className="text-right">
                <span className="text-4xl font-bold text-gray-900">{diversity.diversityScore}%</span>
                <p className="text-sm text-gray-500">综合评分</p>
              </div>
            </div>
          </div>

          {/* 分类分布 */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">分类分布</h3>
            <div className="space-y-3">
              {diversity.categoryDistribution.map((cat) => (
                <div key={cat.name} className="flex items-center justify-between">
                  <span className="text-gray-700">{cat.name}</span>
                  <div className="flex items-center">
                    <div className="w-40 bg-gray-200 rounded-full h-3 mr-4">
                      <div 
                        className={`h-3 rounded-full ${
                          cat.percentage > 50 ? 'bg-orange-500' :
                          cat.percentage < 10 ? 'bg-gray-400' : 'bg-blue-600'
                        }`}
                        style={{ width: `${cat.percentage}%` }}
                      ></div>
                    </div>
                    <span className="text-sm font-medium text-gray-900 w-16 text-right">
                      {cat.percentage}% ({cat.count})
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* 来源分布 */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">来源分布</h3>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
              {diversity.sourceDistribution.slice(0, 8).map((source) => (
                <div key={source.name} className="p-3 bg-gray-50 rounded-lg">
                  <p className="text-sm font-medium text-gray-900 truncate">{source.name}</p>
                  <p className="text-xs text-gray-500">{source.count} 篇 ({source.percentage}%)</p>
                </div>
              ))}
            </div>
          </div>

          {/* 改进建议 */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">改进建议</h3>
            <ul className="space-y-2">
              {diversity.recommendations.map((rec, index) => (
                <li key={index} className="flex items-start">
                  <span className="flex-shrink-0 w-6 h-6 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-xs mr-3 mt-0.5">
                    {index + 1}
                  </span>
                  <span className="text-gray-700">{rec}</span>
                </li>
              ))}
            </ul>
          </div>
        </div>
      )}

      {/* AI趋势分析标签页 */}
      {activeTab === 'trends' && trends && (
        <div className="space-y-6">
          {/* 趋势概述 */}
          <div className="bg-gradient-to-r from-blue-500 to-purple-600 rounded-lg p-6 text-white">
            <h2 className="text-xl font-semibold mb-2">AI发展趋势分析</h2>
            <p className="opacity-90">{trends.summary}</p>
            <p className="text-sm opacity-75 mt-2">
              基于 {trends.totalAnalyzedNews} 篇资讯分析 | 更新时间: {new Date(trends.lastUpdated).toLocaleString('zh-CN')}
            </p>
          </div>

          {/* 三种视角 */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {trends.perspectives.map((perspective) => (
              <div key={perspective.id} className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-lg font-semibold text-gray-900 flex items-center">
                    <span className="text-2xl mr-2">{perspective.icon}</span>
                    {perspective.name}
                  </h3>
                  <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded-full">
                    {perspective.relatedNewsCount} 相关
                  </span>
                </div>
                <p className="text-sm text-gray-600 mb-4">{perspective.description}</p>

                <div className="space-y-3">
                  {perspective.trends.map((trend, index) => (
                    <div key={index} className="border-l-2 border-blue-500 pl-3">
                      <h4 className="font-medium text-gray-900 flex items-center">
                        {trend.title}
                        <span className={`ml-2 text-xs px-1.5 py-0.5 rounded ${
                          trend.relevance === 'high' ? 'bg-red-100 text-red-700' : 'bg-gray-100 text-gray-600'
                        }`}>
                          {trend.relevance === 'high' ? '热门' : '关注'}
                        </span>
                      </h4>
                      <p className="text-sm text-gray-600 mt-1">{trend.description}</p>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default Analytics;
